1	//! `mail-core`: headless fixture mail core for vertical slice 01.
2	//!
3	//! Owns the frozen wire DTOs, a concrete SQLite store with a seed-once
4	//! synthetic inbox, durable receipts with request-key dedup, a single serial
5	//! cancellable archive worker, an injectable clock, an OS-backed profile
6	//! lock, and change subscription. No Tauri, no OAuth, no network, no mail
7	//! beyond the synthetic fixture account. See `docs/vertical-slice-01.md`.
8	
9	pub mod attachments;
10	mod cached_done;
11	pub mod clock;
12	pub mod drafts;
13	pub mod dto;
14	pub mod error;
15	pub mod gmail;
16	pub mod groups;
17	mod lock;
18	pub mod provider;
19	pub mod reminders;
20	pub mod search;
21	mod seed;
22	pub mod splits;
23	pub mod stars;
24	mod store;
25	mod worker;
26	
27	use std::collections::HashMap;
28	use std::path::Path;
29	use std::sync::atomic::{AtomicU64, Ordering};
30	use std::sync::{Arc, Mutex};
31	use std::time::{Duration, Instant};
32	
33	use dto::{
34	    Conversation, ConversationRef, InboxSnapshot, OperationReceipt, SetArchived, UndoOperation,
35	    UndoReceipt,
36	};
37	pub use error::{MailError, ProviderError};
38	use lock::ProfileGuard;
39	pub use provider::{ArchiveProvider, CancelToken, FakeArchiveProvider};
40	use store::Store;
41	use worker::{Notify, WorkerSignal};
42	
43	/// The single synthetic fixture account.
44	pub const ACCOUNT_ID: &str = "fixture-account";
45	/// The fixture's primary mailbox, shared by reader/reply/account metadata.
46	pub const FIXTURE_MAILBOX: &str = "you@fixture.emailos";
47	
48	/// Generous shutdown budget; a paused fake provider is cancelled long before
49	/// this expires. If the join still times out the thread detaches, and the
50	/// interrupted operation stays durable for the next launch.
51	const STOP_JOIN_TIMEOUT: Duration = Duration::from_secs(5);
52	
53	type Listener = Arc<dyn Fn() + Send + Sync>;
54	
55	/// Shared listener registry. Kept separate from the core's inner state so the
56	/// worker's notify closure never creates a reference cycle.
57	struct ListenerHub {
58	    listeners: Mutex<HashMap<u64, Listener>>,
59	}
60	
61	/// Cloneable, thread-safe facade. Cheap to hold from a thin async Tauri
62	/// shell; blocking store calls stay inside [`MailCore`] methods so the shell
63	/// can wrap them in a blocking boundary.
64	pub struct MailCore {
65	    inner: Arc<Inner>,
66	}
67	
68	struct Inner {
69	    store: Arc<Store>,
70	    /// Profile lock is owned for the full core lifetime, and additionally
71	    /// shared with the worker thread: a detached or still-running worker can
72	    /// never outlive the lock (a second writer is rejected instead of two
73	    /// processes corrupting the database).
74	    profile: Arc<ProfileGuard>,
75	    hub: Arc<ListenerHub>,
76	    next_listener_id: AtomicU64,
77	    signal: Arc<WorkerSignal>,
78	    cancel: CancelToken,
79	    worker: Mutex<Option<std::thread::JoinHandle<()>>>,
80	    /// Queryable error surfaced when the worker halted on persistence failure.
81	    halt_sink: Arc<Mutex<Option<MailError>>>,
82	}
83	
84	impl Clone for MailCore {
85	    fn clone(&self) -> Self {
86	        Self {
87	            inner: Arc::clone(&self.inner),
88	        }
89	    }
90	}
91	
92	impl MailCore {
93	    /// Opens (or creates) the synthetic profile storage under `profile_dir`,
94	    /// acquires the profile lock for the full core lifetime, migrates, seeds
95	    /// the 18 synthetic conversations exactly once, and requeues interrupted
96	    /// `applying` operations in original sequence.
97	    pub fn open(profile_dir: impl AsRef<Path>) -> Result<MailCore, MailError> {
98	        Self::open_with_clock(profile_dir, Arc::new(clock::SystemClock))
99	    }
100	
101	    /// Like [`Self::open`] with an injectable clock; tests inject
102	    /// [`clock::FakeClock`] for deterministic undo-window behavior.
103	    pub fn open_with_clock(
104	        profile_dir: impl AsRef<Path>,
105	        clock: Arc<dyn clock::Clock>,
106	    ) -> Result<MailCore, MailError> {
107	        let profile_dir = profile_dir.as_ref();
108	        let profile = Arc::new(ProfileGuard::acquire(profile_dir)?);
109	        let store = Arc::new(Store::open(profile_dir, clock)?);
110	        store.recover_applying()?;
111	        let hub = Arc::new(ListenerHub {
112	            listeners: Mutex::new(HashMap::new()),
113	        });
114	        let halt_sink = Arc::new(Mutex::new(None));
115	        Ok(MailCore {
116	            inner: Arc::new(Inner {
117	                store,
118	                profile,
119	                hub,
120	                next_listener_id: AtomicU64::new(1),
121	                signal: Arc::new(WorkerSignal::new()),
122	                cancel: CancelToken::default(),
123	                worker: Mutex::new(None),
124	                halt_sink,
125	            }),
126	        })
127	    }
128	
129	    /// The single synthetic account id.
130	    pub fn account_id(&self) -> &'static str {
131	        ACCOUNT_ID
132	    }
133	
134	    /// Effective inbox plus persisted activity.
135	    pub fn list_conversations(&self) -> Result<InboxSnapshot, MailError> {
136	        self.ensure_worker_healthy()?;
137	        self.inner.store.list_snapshot()
138	    }
139	
140	    pub fn get_saved_split(
141	        &self,
142	        account: &str,
143	    ) -> Result<Option<crate::splits::SavedSplit>, MailError> {
144	        self.inner.store.get_saved_split(account)
145	    }
146	
147	    pub fn save_saved_split(
148	        &self,
149	        account: &str,
150	        split: &crate::splits::SavedSplit,
151	    ) -> Result<crate::splits::SavedSplit, MailError> {
152	        let saved = self.inner.store.save_saved_split(account, split)?;
153	        self.dispatch();
154	        Ok(saved)
155	    }
156	
157	    pub fn search_mail(
158	        &self,
159	        request: &crate::search::SearchRequest,
160	    ) -> Result<crate::search::SearchPage, MailError> {
161	        self.ensure_worker_healthy()?;
162	        self.inner.store.search_mail(request)
163	    }
164	
165	    pub fn list_cached_done(
166	        &self,
167	        request: &dto::CachedDoneRequest,
168	    ) -> Result<dto::CachedDoneSnapshot, MailError> {
169	        self.ensure_worker_healthy()?;
170	        self.inner.store.list_cached_done(request)
171	    }
172	
173	    /// Reader view of one conversation, scoped by account.
174	    pub fn get_conversation(&self, r#ref: &ConversationRef) -> Result<Conversation, MailError> {
175	        self.ensure_worker_healthy()?;
176	        self.inner.store.get_conversation(r#ref)
177	    }
178	
179	    /// Accepts an archive command: validates, dedups on the request key, and
180	    /// returns a receipt only after commit. Listeners fire after the commit.
181	    pub fn set_archived(&self, command: &SetArchived) -> Result<OperationReceipt, MailError> {
182	        self.ensure_worker_healthy()?;
183	        let receipt = self.inner.store.set_archived(command)?;
184	        self.dispatch();
185	        self.inner.signal.wake();
186	        Ok(receipt)
187	    }
188	
189	    /// Undo of the single latest accepted non-compensating operation
190	    /// (docs/ux-04-trustworthy-undo.md §3.2/§3.3): cancels a still-queued
191	    /// operation in place or stages compensating operations, then wakes the
192	    /// worker so compensation dispatches immediately.
193	    pub fn undo_operation(&self, command: &UndoOperation) -> Result<UndoReceipt, MailError> {
194	        self.ensure_worker_healthy()?;
195	        let receipt = self.inner.store.undo_operation(command)?;
196	        self.dispatch();
197	        self.inner.signal.wake();
198	        Ok(receipt)
199	    }
200	
201	    /// Accepts a bounded archive/unarchive group atomically
202	    /// (docs/ux-05-safe-bulk-processing.md §4.1) and wakes the worker only
203	    /// after the single acceptance commit. Idempotent per `requestId`.
204	    pub fn set_archived_group(
205	        &self,
206	        command: &crate::groups::SetArchivedGroup,
207	    ) -> Result<crate::groups::OperationGroupReceipt, MailError> {
208	        self.ensure_worker_healthy()?;
209	        let receipt = self.inner.store.set_archived_group(command)?;
210	        self.dispatch();
211	        self.inner.signal.wake();
212	        Ok(receipt)
213	    }
214	
215	    /// Active-account group lookup by original acceptance request ID;
216	    /// `Ok(None)` while nothing has committed for that request.
217	    pub fn get_operation_group(
218	        &self,
219	        request: &crate::groups::GetOperationGroupRequest,
220	    ) -> Result<Option<crate::groups::OperationGroupStatus>, MailError> {
221	        self.ensure_worker_healthy()?;
222	        self.inner.store.get_operation_group(request)
223	    }
224	
225	    /// Bounded recent group summaries with cursor, independent of Inbox/Done
226	    /// rows.
227	    pub fn list_operation_groups(
228	        &self,
229	        request: &crate::groups::ListOperationGroupsRequest,
230	    ) -> Result<crate::groups::OperationGroupPage, MailError> {
231	        self.ensure_worker_healthy()?;
232	        self.inner.store.list_operation_groups(request)
233	    }
234	
235	    /// One partial group Undo attempt (docs/ux-05-safe-bulk-processing.md §5);
236	    /// compensation work wakes the worker immediately after commit.
237	    pub fn undo_operation_group(
238	        &self,
239	        command: &crate::groups::UndoOperationGroup,
240	    ) -> Result<crate::groups::GroupUndoReceipt, MailError> {
241	        self.ensure_worker_healthy()?;
242	        let receipt = self.inner.store.undo_operation_group(command)?;
243	        self.dispatch();
244	        self.inner.signal.wake();
245	        Ok(receipt)
246	    }
247	
248	    /// Starts the single serial worker. The provider is injected by the
249	    /// caller (the shell uses [`FakeArchiveProvider::from_env`]). Starting
250	    /// twice is rejected; it is not a valid request field, but the shell
251	    /// treats `invalid_request` with field `worker` as a programming bug.
252	    pub fn start_worker(&self, provider: Arc<dyn ArchiveProvider>) -> Result<(), MailError> {
253	        let mut worker = self
254	            .inner
255	            .worker
256	            .lock()
257	            .map_err(|_| MailError::StorageUnavailable)?;
258	        if worker.is_some() {
259	            return Err(MailError::InvalidRequest {
260	                field: "worker".to_string(),
261	            });
262	        }
263	        *self
264	            .inner
265	            .halt_sink
266	            .lock()
267	            .map_err(|_| MailError::StorageUnavailable)? = None;
268	        let handle = worker::spawn(
269	            Arc::clone(&self.inner.store),
270	            provider,
271	            Arc::clone(&self.inner.signal),
272	            self.inner.cancel.clone(),
273	            {
274	                let hub = Arc::clone(&self.inner.hub);
275	                Arc::new(move || dispatch(&hub)) as Notify
276	            },
277	            {
278	                let sink = Arc::clone(&self.inner.halt_sink);
279	                let hub = Arc::clone(&self.inner.hub);
280	                Arc::new(move |err| {
281	                    *sink.lock().expect("halt sink poisoned") = Some(err);
282	                    dispatch(&hub);
283	                }) as Arc<dyn Fn(MailError) + Send + Sync>
284	            },
285	            Arc::clone(&self.inner.profile),
286	        );
287	        *worker = Some(handle);
288	        Ok(())
289	    }
290	
291	    /// Requests worker shutdown, cancels a paused provider call, and joins
292	    /// the worker thread. Interrupted work stays durable (`applying`) and is
293	    /// requeued on next open.
294	    pub fn stop_worker(&self) {
295	        self.inner.shutdown_worker();
296	    }
297	
298	    /// Whether the worker thread is running.
299	    pub fn is_worker_running(&self) -> bool {
300	        self.inner
301	            .worker
302	            .lock()
303	            .map(|slot| slot.as_ref().is_some_and(|h| !h.is_finished()))
304	            .unwrap_or(false)
305	    }
306	
307	    /// Queryable error indication: set when the worker halted on persistence
308	    /// failure, cleared when the worker restarts. The shell surfaces this in
309	    /// its error state without a DTO change.
310	    pub fn worker_error(&self) -> Option<MailError> {
311	        self.inner
312	            .halt_sink
313	            .lock()
314	            .ok()
315	            .and_then(|sink| sink.clone())
316	    }
317	
318	    /// Registers a change listener and returns an unsubscribe handle. The
319	    /// listener fires after commits (receipts, confirmations, failures) and
320	    /// worker halts; it is a change hint, not a payload.
321	    pub fn subscribe(&self, listener: impl Fn() + Send + Sync + 'static) -> Unsubscribe {
322	        let id = self.inner.next_listener_id.fetch_add(1, Ordering::SeqCst);
323	        self.inner
324	            .hub
325	            .listeners
326	            .lock()
327	            .expect("listener hub poisoned")
328	            .insert(id, Arc::new(listener));
329	        Unsubscribe {
330	            id,
331	            hub: Arc::clone(&self.inner.hub),
332	        }
333	    }
334	
335	    fn ensure_worker_healthy(&self) -> Result<(), MailError> {
336	        let halt = self
337	            .inner
338	            .halt_sink
339	            .lock()
340	            .map_err(|_| MailError::StorageUnavailable)?;
341	        match halt.as_ref() {
342	            Some(error) => Err(error.clone()),
343	            None => Ok(()),
344	        }
345	    }
346	
347	    fn dispatch(&self) {
348	        dispatch(&self.inner.hub);
349	    }
350	}
351	
352	/// Removes the listener when unsubscribed or dropped.
353	#[must_use = "retain this guard for as long as change notifications are needed"]
354	pub struct Unsubscribe {
355	    id: u64,
356	    hub: Arc<ListenerHub>,
357	}
358	
359	impl Unsubscribe {
360	    pub fn unsubscribe(self) {
361	        // Removal happens in Drop.
362	    }
363	}
364	
365	impl Drop for Unsubscribe {
366	    fn drop(&mut self) {
367	        self.hub
368	            .listeners
369	            .lock()
370	            .expect("listener hub poisoned")
371	            .remove(&self.id);
372	    }
373	}
374	
375	fn dispatch(hub: &ListenerHub) {
376	    let listeners: Vec<Listener> = {
377	        let map = hub.listeners.lock().expect("listener hub poisoned");
378	        map.values().cloned().collect()
379	    };
380	    for listener in listeners {
381	        listener();
382	    }
383	}
384	
385	impl Inner {
386	    /// RAII shutdown: cancel the provider call, request stop, join the
387	    /// worker. Runs both from explicit [`MailCore::stop_worker`] and from
388	    /// `Drop` so dropping the core never leaves a worker running. If the
389	    /// join times out, the worker detaches while still holding its own
390	    /// reference to the profile lock, so storage stays exclusively owned.
391	    fn shutdown_worker(&self) {
392	        self.cancel.cancel();
393	        self.signal.request_stop();
394	        let handle = self.worker.lock().ok().and_then(|mut slot| slot.take());
395	        if let Some(handle) = handle {
396	            let deadline = Instant::now() + STOP_JOIN_TIMEOUT;
397	            while !handle.is_finished() {
398	                if Instant::now() >= deadline {
399	                    // Detach; the cancelled operation stays durable and the
400	                    // worker keeps holding the profile lock until it exits.
401	                    return;
402	                }
403	                std::thread::sleep(Duration::from_millis(5));
404	            }
405	            let _ = handle.join();
406	        }
407	    }
408	}
409	
410	impl Drop for Inner {
411	    fn drop(&mut self) {
412	        self.shutdown_worker();
413	    }
414	}
415	
416	#[cfg(test)]
417	mod facade_tests {
418	    use super::*;
419	
420	    #[test]
421	    fn worker_halt_remains_visible_through_commands_after_storage_recovers() {
422	        let dir = std::env::temp_dir().join(format!("mail-core-halt-{}", uuid::Uuid::new_v4()));
423	        let core = MailCore::open(&dir).unwrap();
424	        let (tx, rx) = std::sync::mpsc::channel();
425	        let _subscription = core.subscribe(move || {
426	            let _ = tx.send(());
427	        });
428	        core.inner.store.set_test_persistence_failure(true);
429	        core.start_worker(Arc::new(FakeArchiveProvider::new()))
430	            .unwrap();
431	        rx.recv_timeout(Duration::from_secs(2))
432	            .expect("worker halt notification");
433	        core.inner.store.set_test_persistence_failure(false);
434	
435	        // The underlying DB is readable again, but the worker is still halted.
436	        assert!(core.inner.store.list_snapshot().is_ok());
437	        let target = ConversationRef {
438	            account_id: ACCOUNT_ID.into(),
439	            conversation_id: "conv-01".into(),
440	        };
441	        assert_eq!(
442	            core.list_conversations(),
443	            Err(MailError::StorageUnavailable)
444	        );
445	        assert_eq!(
446	            core.get_conversation(&target),
447	            Err(MailError::StorageUnavailable)
448	        );
449	        assert_eq!(
450	            core.set_archived(&SetArchived {
451	                conversation: target,
452	                archived: true,
453	                request_id: "after-halt".into(),
454	            }),
455	            Err(MailError::StorageUnavailable)
456	        );
457	        assert!(core
458	            .inner
459	            .store
460	            .list_snapshot()
461	            .unwrap()
462	            .activity
463	            .is_empty());
464	        drop(core);
465	        let restarted = MailCore::open(&dir).unwrap();
466	        assert!(restarted.list_conversations().is_ok());
467	        drop(restarted);
468	        std::fs::remove_dir_all(dir).unwrap();
469	    }
470	
471	    /// Core forwarding for the UX-05 group path (docs/ux-05-safe-bulk-processing.md
472	    /// §4): the accepted group's children execute serially through the
473	    /// unchanged worker, the group lookup reflects statuses, and the one-shot
474	    /// group Undo dispatches compensation immediately.
475	    #[test]
476	    fn group_children_execute_serially_and_group_undo_compensates() {
477	        let dir = std::env::temp_dir().join(format!("mail-core-group-{}", uuid::Uuid::new_v4()));
478	        let core = MailCore::open(&dir).unwrap();
479	        core.start_worker(Arc::new(FakeArchiveProvider::new()))
480	            .unwrap();
481	        let receipt = core
482	            .set_archived_group(&crate::groups::SetArchivedGroup {
483	                account_id: ACCOUNT_ID.into(),
484	                members: vec![
485	                    ConversationRef {
486	                        account_id: ACCOUNT_ID.into(),
487	                        conversation_id: "conv-01".into(),
488	                    },
489	                    ConversationRef {
490	                        account_id: ACCOUNT_ID.into(),
491	                        conversation_id: "conv-02".into(),
492	                    },
493	                ],
494	                archived: true,
495	                request_id: "core-group-1".into(),
496	            })
497	            .expect("group accepted");
498	        assert!(
499	            core.set_archived_group(&crate::groups::SetArchivedGroup {
500	                account_id: ACCOUNT_ID.into(),
501	                members: vec![
502	                    ConversationRef {
503	                        account_id: ACCOUNT_ID.into(),
504	                        conversation_id: "conv-02".into()
505	                    },
506	                    ConversationRef {
507	                        account_id: ACCOUNT_ID.into(),
508	                        conversation_id: "conv-01".into()
509	                    },
510	                ],
511	                archived: true,
512	                request_id: "core-group-1".into(),
513	            })
514	            .is_ok(),
515	            "reordered replay is the same request"
516	        );
517	        let child_ids: Vec<String> = receipt
518	            .members
519	            .iter()
520	            .map(|m| m.operation_id.clone().unwrap())
521	            .collect();
522	        // Both members execute serially through the worker.
523	        assert!(wait_for(|| {
524	            core.list_conversations()
525	                .unwrap()
526	                .activity
527	                .iter()
528	                .all(|row| {
529	                    !child_ids.contains(&row.id) || row.status == dto::OperationStatus::Confirmed
530	                })
531	        }));
532	        let status = core
533	            .get_operation_group(&crate::groups::GetOperationGroupRequest {
534	                account_id: ACCOUNT_ID.into(),
535	                request_id: "core-group-1".into(),
536	            })
537	            .unwrap()
538	            .expect("committed group");
539	        assert!(status
540	            .members
541	            .iter()
542	            .all(|m| m.status == crate::groups::GroupMemberStatus::Confirmed));
543	        assert!(status.undo.available, "inside the 10 s window");
544	
545	        // One-shot group Undo: compensation dispatches immediately.
546	        let undo = core
547	            .undo_operation_group(&crate::groups::UndoOperationGroup {
548	                group_id: receipt.group_id.clone(),
549	                request_id: "core-undo-group-1".into(),
550	            })
551	            .expect("group undo");
552	        assert!(undo
553	            .members
554	            .iter()
555	            .all(|m| m.decision == crate::groups::GroupMemberUndoDecision::Compensating));
556	        let compensations: Vec<String> = undo
557	            .members
558	            .iter()
559	            .flat_map(|m| m.operation_ids.clone())
560	            .collect();
561	        assert_eq!(compensations.len(), 2);
562	        assert!(wait_for(|| {
563	            core.list_conversations()
564	                .unwrap()
565	                .activity
566	                .iter()
567	                .all(|row| {
568	                    !compensations.contains(&row.id)
569	                        || row.status == dto::OperationStatus::Confirmed
570	                })
571	        }));
572	        // Restored overlays: both conversations are back in the inbox.
573	        let snapshot = core.list_conversations().unwrap();
574	        for conversation_id in ["conv-01", "conv-02"] {
575	            assert!(snapshot
576	                .conversations
577	                .iter()
578	                .any(|c| c.conversation_ref.conversation_id == conversation_id));
579	        }
580	        // Restart: the group, member outcomes and receipt replay survive.
581	        core.stop_worker();
582	        drop(core);
583	        let reopened = MailCore::open(&dir).unwrap();
584	        assert_eq!(
585	            reopened
586	                .set_archived_group(&crate::groups::SetArchivedGroup {
587	                    account_id: ACCOUNT_ID.into(),
588	                    members: vec![
589	                        ConversationRef {
590	                            account_id: ACCOUNT_ID.into(),
591	                            conversation_id: "conv-01".into()
592	                        },
593	                        ConversationRef {
594	                            account_id: ACCOUNT_ID.into(),
595	                            conversation_id: "conv-02".into()
596	                        },
597	                    ],
598	                    archived: true,
599	                    request_id: "core-group-1".into(),
600	                })
601	                .unwrap(),
602	            receipt,
603	            "same request replays the original receipt after restart"
604	        );
605	        let status = reopened
606	            .get_operation_group(&crate::groups::GetOperationGroupRequest {
607	                account_id: ACCOUNT_ID.into(),
608	                request_id: "core-group-1".into(),
609	            })
610	            .unwrap()
611	            .expect("group survives restart");
612	        assert_eq!(
613	            status.undo.reason,
614	            Some(dto::UndoUnavailableReason::AlreadyUndone),
615	            "group undo outcome survives restart"
616	        );
617	        drop(reopened);
618	        std::fs::remove_dir_all(dir).unwrap();
619	    }
620	
621	    fn wait_for(predicate: impl Fn() -> bool) -> bool {
622	        let deadline = Instant::now() + Duration::from_secs(5);
623	        while !predicate() {
624	            if Instant::now() >= deadline {
625	                return predicate();
626	            }
627	            std::thread::sleep(Duration::from_millis(10));
628	        }
629	        true
630	    }
631	}
