//! `mail-core`: headless fixture mail core for vertical slice 01.
//!
//! Owns the frozen wire DTOs, a concrete SQLite store with a seed-once
//! synthetic inbox, durable receipts with request-key dedup, a single serial
//! cancellable archive worker, an injectable clock, an OS-backed profile
//! lock, and change subscription. No Tauri, no OAuth, no network, no mail
//! beyond the synthetic fixture account. See `docs/vertical-slice-01.md`.

pub mod attachments;
mod cached_done;
pub mod clock;
pub mod drafts;
pub mod dto;
pub mod error;
pub mod gmail;
pub mod groups;
mod lock;
pub mod provider;
pub mod reminders;
pub mod search;
mod seed;
pub mod splits;
pub mod stars;
mod store;
mod worker;

use std::collections::HashMap;
use std::path::Path;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

use dto::{
    Conversation, ConversationRef, InboxSnapshot, OperationReceipt, SetArchived, UndoOperation,
    UndoReceipt,
};
pub use error::{MailError, ProviderError};
use lock::ProfileGuard;
pub use provider::{ArchiveProvider, CancelToken, FakeArchiveProvider};
use store::Store;
use worker::{Notify, WorkerSignal};

/// The single synthetic fixture account.
pub const ACCOUNT_ID: &str = "fixture-account";
/// The fixture's primary mailbox, shared by reader/reply/account metadata.
pub const FIXTURE_MAILBOX: &str = "you@fixture.emailos";

/// Generous shutdown budget; a paused fake provider is cancelled long before
/// this expires. If the join still times out the thread detaches, and the
/// interrupted operation stays durable for the next launch.
const STOP_JOIN_TIMEOUT: Duration = Duration::from_secs(5);

type Listener = Arc<dyn Fn() + Send + Sync>;

/// Shared listener registry. Kept separate from the core's inner state so the
/// worker's notify closure never creates a reference cycle.
struct ListenerHub {
    listeners: Mutex<HashMap<u64, Listener>>,
}

/// Cloneable, thread-safe facade. Cheap to hold from a thin async Tauri
/// shell; blocking store calls stay inside [`MailCore`] methods so the shell
/// can wrap them in a blocking boundary.
pub struct MailCore {
    inner: Arc<Inner>,
}

struct Inner {
    store: Arc<Store>,
    /// Profile lock is owned for the full core lifetime, and additionally
    /// shared with the worker thread: a detached or still-running worker can
    /// never outlive the lock (a second writer is rejected instead of two
    /// processes corrupting the database).
    profile: Arc<ProfileGuard>,
    hub: Arc<ListenerHub>,
    next_listener_id: AtomicU64,
    signal: Arc<WorkerSignal>,
    cancel: CancelToken,
    worker: Mutex<Option<std::thread::JoinHandle<()>>>,
    /// Queryable error surfaced when the worker halted on persistence failure.
    halt_sink: Arc<Mutex<Option<MailError>>>,
}

impl Clone for MailCore {
    fn clone(&self) -> Self {
        Self {
            inner: Arc::clone(&self.inner),
        }
    }
}

impl MailCore {
    /// Opens (or creates) the synthetic profile storage under `profile_dir`,
    /// acquires the profile lock for the full core lifetime, migrates, seeds
    /// the 18 synthetic conversations exactly once, and requeues interrupted
    /// `applying` operations in original sequence.
    pub fn open(profile_dir: impl AsRef<Path>) -> Result<MailCore, MailError> {
        Self::open_with_clock(profile_dir, Arc::new(clock::SystemClock))
    }

    /// Like [`Self::open`] with an injectable clock; tests inject
    /// [`clock::FakeClock`] for deterministic undo-window behavior.
    pub fn open_with_clock(
        profile_dir: impl AsRef<Path>,
        clock: Arc<dyn clock::Clock>,
    ) -> Result<MailCore, MailError> {
        let profile_dir = profile_dir.as_ref();
        let profile = Arc::new(ProfileGuard::acquire(profile_dir)?);
        let store = Arc::new(Store::open(profile_dir, clock)?);
        store.recover_applying()?;
        let hub = Arc::new(ListenerHub {
            listeners: Mutex::new(HashMap::new()),
        });
        let halt_sink = Arc::new(Mutex::new(None));
        Ok(MailCore {
            inner: Arc::new(Inner {
                store,
                profile,
                hub,
                next_listener_id: AtomicU64::new(1),
                signal: Arc::new(WorkerSignal::new()),
                cancel: CancelToken::default(),
                worker: Mutex::new(None),
                halt_sink,
            }),
        })
    }

    /// The single synthetic account id.
    pub fn account_id(&self) -> &'static str {
        ACCOUNT_ID
    }

    /// Effective inbox plus persisted activity.
    pub fn list_conversations(&self) -> Result<InboxSnapshot, MailError> {
        self.ensure_worker_healthy()?;
        self.inner.store.list_snapshot()
    }

    pub fn get_saved_split(
        &self,
        account: &str,
    ) -> Result<Option<crate::splits::SavedSplit>, MailError> {
        self.inner.store.get_saved_split(account)
    }

    pub fn save_saved_split(
        &self,
        account: &str,
        split: &crate::splits::SavedSplit,
    ) -> Result<crate::splits::SavedSplit, MailError> {
        let saved = self.inner.store.save_saved_split(account, split)?;
        self.dispatch();
        Ok(saved)
    }

    pub fn search_mail(
        &self,
        request: &crate::search::SearchRequest,
    ) -> Result<crate::search::SearchPage, MailError> {
        self.ensure_worker_healthy()?;
        self.inner.store.search_mail(request)
    }

    pub fn list_cached_done(
        &self,
        request: &dto::CachedDoneRequest,
    ) -> Result<dto::CachedDoneSnapshot, MailError> {
        self.ensure_worker_healthy()?;
        self.inner.store.list_cached_done(request)
    }

    /// Reader view of one conversation, scoped by account.
    pub fn get_conversation(&self, r#ref: &ConversationRef) -> Result<Conversation, MailError> {
        self.ensure_worker_healthy()?;
        self.inner.store.get_conversation(r#ref)
    }

    /// Accepts an archive command: validates, dedups on the request key, and
    /// returns a receipt only after commit. Listeners fire after the commit.
    pub fn set_archived(&self, command: &SetArchived) -> Result<OperationReceipt, MailError> {
        self.ensure_worker_healthy()?;
        let receipt = self.inner.store.set_archived(command)?;
        self.dispatch();
        self.inner.signal.wake();
        Ok(receipt)
    }

    /// Undo of the single latest accepted non-compensating operation
    /// (docs/ux-04-trustworthy-undo.md §3.2/§3.3): cancels a still-queued
    /// operation in place or stages compensating operations, then wakes the
    /// worker so compensation dispatches immediately.
    pub fn undo_operation(&self, command: &UndoOperation) -> Result<UndoReceipt, MailError> {
        self.ensure_worker_healthy()?;
        let receipt = self.inner.store.undo_operation(command)?;
        self.dispatch();
        self.inner.signal.wake();
        Ok(receipt)
    }

    /// Accepts a bounded archive/unarchive group atomically
    /// (docs/ux-05-safe-bulk-processing.md §4.1) and wakes the worker only
    /// after the single acceptance commit. Idempotent per `requestId`.
    pub fn set_archived_group(
        &self,
        command: &crate::groups::SetArchivedGroup,
    ) -> Result<crate::groups::OperationGroupReceipt, MailError> {
        self.ensure_worker_healthy()?;
        let receipt = self.inner.store.set_archived_group(command)?;
        self.dispatch();
        self.inner.signal.wake();
        Ok(receipt)
    }

    /// Active-account group lookup by original acceptance request ID;
    /// `Ok(None)` while nothing has committed for that request.
    pub fn get_operation_group(
        &self,
        request: &crate::groups::GetOperationGroupRequest,
    ) -> Result<Option<crate::groups::OperationGroupStatus>, MailError> {
        self.ensure_worker_healthy()?;
        self.inner.store.get_operation_group(request)
    }

    /// Bounded recent group summaries with cursor, independent of Inbox/Done
    /// rows.
    pub fn list_operation_groups(
        &self,
        request: &crate::groups::ListOperationGroupsRequest,
    ) -> Result<crate::groups::OperationGroupPage, MailError> {
        self.ensure_worker_healthy()?;
        self.inner.store.list_operation_groups(request)
    }

    /// One partial group Undo attempt (docs/ux-05-safe-bulk-processing.md §5);
    /// compensation work wakes the worker immediately after commit.
    pub fn undo_operation_group(
        &self,
        command: &crate::groups::UndoOperationGroup,
    ) -> Result<crate::groups::GroupUndoReceipt, MailError> {
        self.ensure_worker_healthy()?;
        let receipt = self.inner.store.undo_operation_group(command)?;
        self.dispatch();
        self.inner.signal.wake();
        Ok(receipt)
    }

    /// Starts the single serial worker. The provider is injected by the
    /// caller (the shell uses [`FakeArchiveProvider::from_env`]). Starting
    /// twice is rejected; it is not a valid request field, but the shell
    /// treats `invalid_request` with field `worker` as a programming bug.
    pub fn start_worker(&self, provider: Arc<dyn ArchiveProvider>) -> Result<(), MailError> {
        let mut worker = self
            .inner
            .worker
            .lock()
            .map_err(|_| MailError::StorageUnavailable)?;
        if worker.is_some() {
            return Err(MailError::InvalidRequest {
                field: "worker".to_string(),
            });
        }
        *self
            .inner
            .halt_sink
            .lock()
            .map_err(|_| MailError::StorageUnavailable)? = None;
        let handle = worker::spawn(
            Arc::clone(&self.inner.store),
            provider,
            Arc::clone(&self.inner.signal),
            self.inner.cancel.clone(),
            {
                let hub = Arc::clone(&self.inner.hub);
                Arc::new(move || dispatch(&hub)) as Notify
            },
            {
                let sink = Arc::clone(&self.inner.halt_sink);
                let hub = Arc::clone(&self.inner.hub);
                Arc::new(move |err| {
                    *sink.lock().expect("halt sink poisoned") = Some(err);
                    dispatch(&hub);
                }) as Arc<dyn Fn(MailError) + Send + Sync>
            },
            Arc::clone(&self.inner.profile),
        );
        *worker = Some(handle);
        Ok(())
    }

    /// Requests worker shutdown, cancels a paused provider call, and joins
    /// the worker thread. Interrupted work stays durable (`applying`) and is
    /// requeued on next open.
    pub fn stop_worker(&self) {
        self.inner.shutdown_worker();
    }

    /// Whether the worker thread is running.
    pub fn is_worker_running(&self) -> bool {
        self.inner
            .worker
            .lock()
            .map(|slot| slot.as_ref().is_some_and(|h| !h.is_finished()))
            .unwrap_or(false)
    }

    /// Queryable error indication: set when the worker halted on persistence
    /// failure, cleared when the worker restarts. The shell surfaces this in
    /// its error state without a DTO change.
    pub fn worker_error(&self) -> Option<MailError> {
        self.inner
            .halt_sink
            .lock()
            .ok()
            .and_then(|sink| sink.clone())
    }

    /// Registers a change listener and returns an unsubscribe handle. The
    /// listener fires after commits (receipts, confirmations, failures) and
    /// worker halts; it is a change hint, not a payload.
    pub fn subscribe(&self, listener: impl Fn() + Send + Sync + 'static) -> Unsubscribe {
        let id = self.inner.next_listener_id.fetch_add(1, Ordering::SeqCst);
        self.inner
            .hub
            .listeners
            .lock()
            .expect("listener hub poisoned")
            .insert(id, Arc::new(listener));
        Unsubscribe {
            id,
            hub: Arc::clone(&self.inner.hub),
        }
    }

    fn ensure_worker_healthy(&self) -> Result<(), MailError> {
        let halt = self
            .inner
            .halt_sink
            .lock()
            .map_err(|_| MailError::StorageUnavailable)?;
        match halt.as_ref() {
            Some(error) => Err(error.clone()),
            None => Ok(()),
        }
    }

    fn dispatch(&self) {
        dispatch(&self.inner.hub);
    }
}

/// Removes the listener when unsubscribed or dropped.
#[must_use = "retain this guard for as long as change notifications are needed"]
pub struct Unsubscribe {
    id: u64,
    hub: Arc<ListenerHub>,
}

impl Unsubscribe {
    pub fn unsubscribe(self) {
        // Removal happens in Drop.
    }
}

impl Drop for Unsubscribe {
    fn drop(&mut self) {
        self.hub
            .listeners
            .lock()
            .expect("listener hub poisoned")
            .remove(&self.id);
    }
}

fn dispatch(hub: &ListenerHub) {
    let listeners: Vec<Listener> = {
        let map = hub.listeners.lock().expect("listener hub poisoned");
        map.values().cloned().collect()
    };
    for listener in listeners {
        listener();
    }
}

impl Inner {
    /// RAII shutdown: cancel the provider call, request stop, join the
    /// worker. Runs both from explicit [`MailCore::stop_worker`] and from
    /// `Drop` so dropping the core never leaves a worker running. If the
    /// join times out, the worker detaches while still holding its own
    /// reference to the profile lock, so storage stays exclusively owned.
    fn shutdown_worker(&self) {
        self.cancel.cancel();
        self.signal.request_stop();
        let handle = self.worker.lock().ok().and_then(|mut slot| slot.take());
        if let Some(handle) = handle {
            let deadline = Instant::now() + STOP_JOIN_TIMEOUT;
            while !handle.is_finished() {
                if Instant::now() >= deadline {
                    // Detach; the cancelled operation stays durable and the
                    // worker keeps holding the profile lock until it exits.
                    return;
                }
                std::thread::sleep(Duration::from_millis(5));
            }
            let _ = handle.join();
        }
    }
}

impl Drop for Inner {
    fn drop(&mut self) {
        self.shutdown_worker();
    }
}

#[cfg(test)]
mod facade_tests {
    use super::*;

    #[test]
    fn worker_halt_remains_visible_through_commands_after_storage_recovers() {
        let dir = std::env::temp_dir().join(format!("mail-core-halt-{}", uuid::Uuid::new_v4()));
        let core = MailCore::open(&dir).unwrap();
        let (tx, rx) = std::sync::mpsc::channel();
        let _subscription = core.subscribe(move || {
            let _ = tx.send(());
        });
        core.inner.store.set_test_persistence_failure(true);
        core.start_worker(Arc::new(FakeArchiveProvider::new()))
            .unwrap();
        rx.recv_timeout(Duration::from_secs(2))
            .expect("worker halt notification");
        core.inner.store.set_test_persistence_failure(false);

        // The underlying DB is readable again, but the worker is still halted.
        assert!(core.inner.store.list_snapshot().is_ok());
        let target = ConversationRef {
            account_id: ACCOUNT_ID.into(),
            conversation_id: "conv-01".into(),
        };
        assert_eq!(
            core.list_conversations(),
            Err(MailError::StorageUnavailable)
        );
        assert_eq!(
            core.get_conversation(&target),
            Err(MailError::StorageUnavailable)
        );
        assert_eq!(
            core.set_archived(&SetArchived {
                conversation: target,
                archived: true,
                request_id: "after-halt".into(),
            }),
            Err(MailError::StorageUnavailable)
        );
        assert!(core
            .inner
            .store
            .list_snapshot()
            .unwrap()
            .activity
            .is_empty());
        drop(core);
        let restarted = MailCore::open(&dir).unwrap();
        assert!(restarted.list_conversations().is_ok());
        drop(restarted);
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// Core forwarding for the UX-05 group path (docs/ux-05-safe-bulk-processing.md
    /// §4): the accepted group's children execute serially through the
    /// unchanged worker, the group lookup reflects statuses, and the one-shot
    /// group Undo dispatches compensation immediately.
    #[test]
    fn group_children_execute_serially_and_group_undo_compensates() {
        let dir = std::env::temp_dir().join(format!("mail-core-group-{}", uuid::Uuid::new_v4()));
        let core = MailCore::open(&dir).unwrap();
        core.start_worker(Arc::new(FakeArchiveProvider::new()))
            .unwrap();
        let receipt = core
            .set_archived_group(&crate::groups::SetArchivedGroup {
                account_id: ACCOUNT_ID.into(),
                members: vec![
                    ConversationRef {
                        account_id: ACCOUNT_ID.into(),
                        conversation_id: "conv-01".into(),
                    },
                    ConversationRef {
                        account_id: ACCOUNT_ID.into(),
                        conversation_id: "conv-02".into(),
                    },
                ],
                archived: true,
                request_id: "core-group-1".into(),
            })
            .expect("group accepted");
        assert!(
            core.set_archived_group(&crate::groups::SetArchivedGroup {
                account_id: ACCOUNT_ID.into(),
                members: vec![
                    ConversationRef {
                        account_id: ACCOUNT_ID.into(),
                        conversation_id: "conv-02".into()
                    },
                    ConversationRef {
                        account_id: ACCOUNT_ID.into(),
                        conversation_id: "conv-01".into()
                    },
                ],
                archived: true,
                request_id: "core-group-1".into(),
            })
            .is_ok(),
            "reordered replay is the same request"
        );
        let child_ids: Vec<String> = receipt
            .members
            .iter()
            .map(|m| m.operation_id.clone().unwrap())
            .collect();
        // Both members execute serially through the worker.
        assert!(wait_for(|| {
            core.list_conversations()
                .unwrap()
                .activity
                .iter()
                .all(|row| {
                    !child_ids.contains(&row.id) || row.status == dto::OperationStatus::Confirmed
                })
        }));
        let status = core
            .get_operation_group(&crate::groups::GetOperationGroupRequest {
                account_id: ACCOUNT_ID.into(),
                request_id: "core-group-1".into(),
            })
            .unwrap()
            .expect("committed group");
        assert!(status
            .members
            .iter()
            .all(|m| m.status == crate::groups::GroupMemberStatus::Confirmed));
        assert!(status.undo.available, "inside the 10 s window");

        // One-shot group Undo: compensation dispatches immediately.
        let undo = core
            .undo_operation_group(&crate::groups::UndoOperationGroup {
                group_id: receipt.group_id.clone(),
                request_id: "core-undo-group-1".into(),
            })
            .expect("group undo");
        assert!(undo
            .members
            .iter()
            .all(|m| m.decision == crate::groups::GroupMemberUndoDecision::Compensating));
        let compensations: Vec<String> = undo
            .members
            .iter()
            .flat_map(|m| m.operation_ids.clone())
            .collect();
        assert_eq!(compensations.len(), 2);
        assert!(wait_for(|| {
            core.list_conversations()
                .unwrap()
                .activity
                .iter()
                .all(|row| {
                    !compensations.contains(&row.id)
                        || row.status == dto::OperationStatus::Confirmed
                })
        }));
        // Restored overlays: both conversations are back in the inbox.
        let snapshot = core.list_conversations().unwrap();
        for conversation_id in ["conv-01", "conv-02"] {
            assert!(snapshot
                .conversations
                .iter()
                .any(|c| c.conversation_ref.conversation_id == conversation_id));
        }
        // Restart: the group, member outcomes and receipt replay survive.
        core.stop_worker();
        drop(core);
        let reopened = MailCore::open(&dir).unwrap();
        assert_eq!(
            reopened
                .set_archived_group(&crate::groups::SetArchivedGroup {
                    account_id: ACCOUNT_ID.into(),
                    members: vec![
                        ConversationRef {
                            account_id: ACCOUNT_ID.into(),
                            conversation_id: "conv-01".into()
                        },
                        ConversationRef {
                            account_id: ACCOUNT_ID.into(),
                            conversation_id: "conv-02".into()
                        },
                    ],
                    archived: true,
                    request_id: "core-group-1".into(),
                })
                .unwrap(),
            receipt,
            "same request replays the original receipt after restart"
        );
        let status = reopened
            .get_operation_group(&crate::groups::GetOperationGroupRequest {
                account_id: ACCOUNT_ID.into(),
                request_id: "core-group-1".into(),
            })
            .unwrap()
            .expect("group survives restart");
        assert_eq!(
            status.undo.reason,
            Some(dto::UndoUnavailableReason::AlreadyUndone),
            "group undo outcome survives restart"
        );
        drop(reopened);
        std::fs::remove_dir_all(dir).unwrap();
    }

    fn wait_for(predicate: impl Fn() -> bool) -> bool {
        let deadline = Instant::now() + Duration::from_secs(5);
        while !predicate() {
            if Instant::now() >= deadline {
                return predicate();
            }
            std::thread::sleep(Duration::from_millis(10));
        }
        true
    }
}

