//! Coordinator tooling (not part of the repo): seeds a Gmail-mode profile through the real
//! GmailCore/GmailStore with the scripted fake provider, or dumps what a build reads from one.
use mail_core::clock::{utc, FakeClock};
use mail_core::dto::{CachedDoneRequest, ConversationRef, OperationStatus, SetArchived, SetRead};
use mail_core::error::MailError;
use mail_core::gmail::sync::GmailCore;
use mail_core::gmail::types::{ConnectionState, GmailThread, SyncState};
use mail_core::groups::{ListOperationGroupsRequest, SetArchivedGroup};
use mail_core::reminders::{PutReminder, ReminderCondition};
use mail_core::splits::{SavedSplit, SplitCriterion};
use mail_core::testing::operations_fake::{ApplyPlan, FakeProvider};
use mail_core::testing::{message, open_core, open_core_with_clock, thread, until};
use std::sync::Arc;
use std::time::Duration;

const ACCOUNT: &str = "acct-upgrade";

fn cref(id: &str) -> ConversationRef {
    ConversationRef { account_id: ACCOUNT.into(), conversation_id: id.into() }
}
fn threads() -> Vec<GmailThread> {
    (1..=6)
        .map(|i| {
            let mid = format!("m-{i}");
            thread(
                ACCOUNT,
                &format!("t-{i}"),
                vec![message(&mid, &format!("sender{i}@example.test"), &format!("2026-01-0{i}T00:00:00Z"), &format!("synthetic body {i}"))],
                &[mid.as_str()],
                Some(vec![mid.clone()]),
                "history-1",
            )
        })
        .collect()
}
fn status_of(core: &GmailCore, op: &str) -> Option<OperationStatus> {
    core.list_conversations().unwrap().activity.iter().find(|o| o.id == op).map(|o| o.status.clone())
}
fn wait_confirmed(core: &GmailCore, op: &str) {
    assert!(until(|| status_of(core, op) == Some(OperationStatus::Confirmed)), "op {op} not confirmed");
}

fn seed(dir: &str) {
    let provider = FakeProvider::with_threads(threads());
    let core = open_core(dir, &provider);
    assert!(until(|| {
        let s = core.account_status().unwrap();
        s.connection == ConnectionState::Connected && s.sync.initial_sync_complete && s.sync.state == SyncState::Idle
            && core.list_conversations().unwrap().conversations.len() == 6
    }), "seed sync did not complete: {:?}", core.account_status());
    let a = core.set_archived(&SetArchived { conversation: cref("t-1"), archived: true, request_id: "seed-archive-1".into() }).unwrap();
    wait_confirmed(&core, &a.operation_id);
    let r = core.set_read(&SetRead { conversation: cref("t-2"), read: true, request_id: "seed-read-2".into() }).unwrap();
    wait_confirmed(&core, &r.operation_id);
    let g = core.set_archived_group(&SetArchivedGroup { account_id: ACCOUNT.into(), members: vec![cref("t-3"), cref("t-4")], archived: true, request_id: "seed-group-34".into() }).unwrap();
    for m in &g.members { wait_confirmed(&core, m.operation_id.as_ref().unwrap()); }
    core.save_saved_split(ACCOUNT, &SavedSplit { name: "Example".into(), criterion: SplitCriterion::Domain, value: "example.test".into(), enabled: true, hide_when_empty: false }).unwrap();
    core.put_reminder(&PutReminder { conversation: cref("t-5"), source_message_id: "m-5".into(), due_at: Some("2099-01-01T00:00:00Z".into()), condition: ReminderCondition::Regardless, expected_revision: None, request_id: "seed-reminder-5".into() }).unwrap();
    core.wait_for_test_idle(Duration::from_secs(5)).unwrap();
    // Leave one accepted operation queued: the provider refuses before dispatch.
    provider.set_apply_plan(ApplyPlan::BeforeDispatchError(MailError::NetworkUnavailable));
    let q = core.set_archived(&SetArchived { conversation: cref("t-6"), archived: true, request_id: "seed-queued-6".into() }).unwrap();
    assert!(until(|| core.list_conversations().unwrap().activity.iter().any(|o| o.id == q.operation_id && o.status == OperationStatus::Queued && o.last_error.is_some())), "queued op did not settle");
    core.stop();
    drop(core);
    println!("seeded {dir}");
}

fn dump(dir: &str) {
    let provider = FakeProvider::with_threads(threads());
    // Offline: nothing the provider says may change the profile while we read it.
    provider.set_sticky_error(Some(MailError::NetworkUnavailable));
    let clock = Arc::new(FakeClock::new(utc("2030-01-01T00:00:00Z")));
    let core = open_core_with_clock(dir, &provider, &clock);
    let _ = core.wait_for_test_idle(Duration::from_secs(5));
    let inbox = core.list_conversations().unwrap();
    let mut out = serde_json::Map::new();
    let status = core.account_status().unwrap();
    out.insert("account".into(), serde_json::to_value(&status.account).unwrap());
    out.insert("mode".into(), serde_json::to_value(&status.mode).unwrap());
    out.insert("cachedConversations".into(), serde_json::to_value(status.sync.cached_conversations).unwrap());
    out.insert("initialSyncComplete".into(), serde_json::to_value(status.sync.initial_sync_complete).unwrap());
    out.insert("lastSyncedAt".into(), serde_json::to_value(&status.sync.last_synced_at).unwrap());
    out.insert("inbox".into(), serde_json::to_value(&inbox.conversations).unwrap());
    out.insert("activity".into(), serde_json::to_value(&inbox.activity).unwrap());
    out.insert("done".into(), serde_json::to_value(core.list_cached_done(&CachedDoneRequest { account_id: ACCOUNT.into(), limit: 100, cursor: None }).unwrap()).unwrap());
    out.insert("reminders".into(), serde_json::to_value(core.list_reminders().unwrap()).unwrap());
    out.insert("split".into(), serde_json::to_value(core.get_saved_split(ACCOUNT).unwrap()).unwrap());
    out.insert("groups".into(), serde_json::to_value(core.list_operation_groups(&ListOperationGroupsRequest { account_id: ACCOUNT.into(), limit: 50, cursor: None }).unwrap()).unwrap());
    for i in 1..=6 {
        let id = format!("t-{i}");
        out.insert(format!("conversation:{id}"), serde_json::to_value(core.get_conversation(&cref(&id)).map_err(|e| format!("{e:?}"))).unwrap());
    }
    core.stop();
    drop(core);
    println!("{}", serde_json::to_string_pretty(&serde_json::Value::Object(out)).unwrap());
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    match (args.get(1).map(String::as_str), args.get(2)) {
        (Some("seed"), Some(dir)) => seed(dir),
        (Some("dump"), Some(dir)) => dump(dir),
        _ => { eprintln!("usage: gmail-upgrade-check seed|dump <profile-dir>"); std::process::exit(2) }
    }
}
