        self.run(Step::MarkDone)?;
        let backup = read_marker(dir)
            .ok()
            .flatten()
            .and_then(|marker| marker.backup);
        write_marker(
            dir,
            &Marker {
                version: 1,
                state: MarkerState::Done,
                backup,
            },
        )
        .map_err(|_| Stop::Failed)
